<?php
namespace qqworld_collector\module\artificial_intelligence; if (!defined('ABSPATH')) { exit; } class QQWorld_AI_Weather { const SEARCH_URL = "https://toy1.weather.com.cn/search?cityname={query}&callback=success_jsonpCallback&_={ts}"; const WEATHER_URL = "https://www.weather.com.cn/weather/{code}.shtml"; const REQUEST_TIMEOUT = 15; private static $REQUEST_HEADERS = array( "User-Agent" => "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36", "Accept" => "*/*", "Accept-Language" => "zh-CN,zh;q=0.9,en;q=0.8", "Referer" => "https://www.weather.com.cn/", ); private static $LIFE_INDEX_NAMES = array( "感冒" => "cold", "运动" => "exercise", "过敏" => "allergy", "穿衣" => "clothing", "洗车" => "carwash", "紫外线" => "uv", "钓鱼" => "fishing", "旅游" => "travel", "晾晒" => "drying", "交通" => "traffic", "防晒" => "sunscreen", ); private $preset_cities = array(); private $codes_file_path = ''; public function __construct() { $this->codes_file_path = dirname(__FILE__) . '/skills/weather-skill/citys.txt'; $this->preset_cities = $this->load_preset_cities(); } private function load_preset_cities() { $cities = array(); if (!file_exists($this->codes_file_path)) { return $cities; } try { $lines = file($this->codes_file_path, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES); foreach ($lines as $line) { $line = trim($line); if (empty($line) || strpos($line, '#') === 0) { continue; } $parts = explode(',', $line); if (count($parts) >= 2) { $city_name = trim($parts[0]); $city_code = trim($parts[1]); $cities[$city_name] = $city_code; } } } catch (\Exception $e) { error_log('[QQWorld AI Weather] Warning: Failed to read citys.txt - ' . $e->getMessage()); } return $cities; } private function save_new_city($city_name, $city_code) { try { $handle = fopen($this->codes_file_path, 'a'); if ($handle) { fwrite($handle, $city_name . ',' . $city_code . "\n"); fclose($handle); $this->preset_cities[$city_name] = $city_code; } } catch (\Exception $e) { error_log('[QQWorld AI Weather] Warning: Failed to save city to citys.txt - ' . $e->getMessage()); } } private function http_get($url, $encoding = 'utf-8') { $response = wp_remote_get($url, array( 'timeout' => self::REQUEST_TIMEOUT, 'sslverify' => false, 'headers' => self::$REQUEST_HEADERS, )); if (is_wp_error($response)) { throw new \RuntimeException('HTTP request failed: ' . $url . ' - ' . $response->get_error_message()); } $body = wp_remote_retrieve_body($response); return mb_convert_encoding($body, 'UTF-8', $encoding); } private function search_city($city_name) { $encoded = urlencode($city_name); $ts = time() * 1000; $url = str_replace(array('{query}', '{ts}'), array($encoded, $ts), self::SEARCH_URL); try { $text = $this->http_get($url); } catch (\RuntimeException $e) { return null; } if (!preg_match('/success_jsonpCallback\((\[.*\])\)/s', $text, $match)) { return null; } try { $results = json_decode($match[1], true); } catch (\Exception $e) { return null; } if (!is_array($results) || empty($results)) { return null; } $ref = isset($results[0]['ref']) ? $results[0]['ref'] : ''; $parts = explode('~', $ref); if (count($parts) >= 3) { $code = $parts[0]; $display_name = $parts[2]; if (preg_match('/^101\d{6}$/', $code)) { return array($code, $display_name); } } return null; } public function get_city_code($city_name) { $city_name = trim($city_name); if (isset($this->preset_cities[$city_name])) { return array($this->preset_cities[$city_name], $city_name); } $result = $this->search_city($city_name); if ($result) { list($code, $display_name) = $result; $this->save_new_city($city_name, $code); if ($display_name !== $city_name) { $this->save_new_city($display_name, $code); } return $result; } throw new \InvalidArgumentException('未找到城市: ' . $city_name); } private function fetch_weather_html($city_code) { $url = str_replace('{code}', $city_code, self::WEATHER_URL); return $this->http_get($url); } private function extract_div_content($html, $target_id) { libxml_use_internal_errors(true); $doc = new \DOMDocument(); $doc->loadHTML('<?xml encoding="UTF-8">' . $html); $xpath = new \DOMXPath($doc); $nodes = $xpath->query('//div[@id="' . $target_id . '"]'); if ($nodes->length > 0) { $inner_html = ''; foreach ($nodes->item(0)->childNodes as $child) { $inner_html .= $doc->saveHTML($child); } return $inner_html; } libxml_clear_errors(); return ''; } private function parse_7day_forecast($html) { libxml_use_internal_errors(true); $doc = new \DOMDocument(); $doc->loadHTML('<?xml encoding="UTF-8">' . $html); $xpath = new \DOMXPath($doc); $forecasts = array(); $nodes = $xpath->query('//div[@id="7d"]//li'); foreach ($nodes as $li) { $h1 = $xpath->query('./h1', $li)->item(0); if (!$h1) continue; $day = array( 'date' => trim($h1->textContent), 'weather' => '', 'temp_high' => '', 'temp_low' => '', 'wind' => '', 'wind_level' => '', ); $wea = $xpath->query('./p[@class="wea"]', $li)->item(0); if ($wea) { $day['weather'] = trim($wea->textContent); } $tem = $xpath->query('./p[@class="tem"]', $li)->item(0); if ($tem) { $span = $xpath->query('./span', $tem)->item(0); $i_tag = $xpath->query('./i', $tem)->item(0); if ($span) { $day['temp_high'] = trim($span->textContent) . '℃'; } if ($i_tag) { $temp_text = trim($i_tag->textContent); if (!empty($temp_text)) { $day['temp_low'] = str_replace('℃', '', $temp_text) . '℃'; } } } $win = $xpath->query('./p[@class="win"]', $li)->item(0); if ($win) { $em_span = $xpath->query('./em/span', $win)->item(0); $wind_i = $xpath->query('./i', $win)->item(0); if ($em_span) { $day['wind'] = $em_span->getAttribute('title'); } if ($wind_i) { $day['wind_level'] = trim($wind_i->textContent); } } $forecasts[] = $day; } libxml_clear_errors(); return $forecasts; } private function parse_life_indices($html) { $block = $this->extract_div_content($html, 'livezs'); if (empty($block)) { return array(); } $indices = array(); preg_match_all('/<li[^>]*>(.*?)<\/li>/s', $block, $li_blocks); foreach ($li_blocks[1] as $li) { $m_level = preg_match('/<span>([^<]+)<\/span>/', $li, $level_match); $m_name = preg_match('/<em>([^<]+)<\/em>/', $li, $name_match); $m_desc = preg_match('/<p>([^<]+)<\/p>/', $li, $desc_match); if (!$m_level || !$m_name) { continue; } $level = trim($level_match[1]); $name = trim($name_match[1]); $desc = $m_desc ? trim($desc_match[1]) : ''; $index_type = str_replace('指数', '', $name); $key = isset(self::$LIFE_INDEX_NAMES[$index_type]) ? self::$LIFE_INDEX_NAMES[$index_type] : $index_type; $indices[] = array( 'name' => $name, 'key' => $key, 'level' => $level, 'description' => $desc, ); } return $indices; } public function query($city_name) { try { list($code, $display_name) = $this->get_city_code($city_name); $html = $this->fetch_weather_html($code); $forecast = $this->parse_7day_forecast($html); $life_indices = $this->parse_life_indices($html); if (!empty($forecast) && !empty($life_indices)) { $num_days = count($forecast); $indices_per_day = (int)(count($life_indices) / $num_days); if ($indices_per_day > 0) { foreach ($forecast as $i => $day) { $start = $i * $indices_per_day; $end = $start + $indices_per_day; $forecast[$i]['life_indices'] = array_slice($life_indices, $start, $indices_per_day); } } else { $forecast[0]['life_indices'] = $life_indices; } } return array( 'city' => $display_name, 'city_code' => $code, 'query_time' => date('Y-m-d H:i:s'), 'source' => 'weather.com.cn', 'forecast' => $forecast, ); } catch (\InvalidArgumentException $e) { return array('error' => $e->getMessage()); } catch (\RuntimeException $e) { return array('error' => '网络错误: ' . $e->getMessage()); } catch (\Exception $e) { return array('error' => '未知错误: ' . $e->getMessage()); } } public function format_output($data) { if (isset($data['error'])) { return '错误: ' . $data['error']; } $lines = array( '城市: ' . $data['city'] . ' (代码: ' . $data['city_code'] . ')', '数据来源: ' . $data['source'], '查询时间: ' . $data['query_time'], ); foreach ($data['forecast'] as $day) { $lines[] = ''; $temp = (!empty($day['temp_high'])) ? $day['temp_high'] . '/' . $day['temp_low'] : $day['temp_low']; $wind_info = (!empty($day['wind'])) ? $day['wind'] . ' ' . $day['wind_level'] : ''; $lines[] = '[' . $day['date'] . '] ' . $day['weather'] . ', ' . $temp . ', ' . rtrim($wind_info, ' '); if (!empty($day['life_indices'])) { foreach ($day['life_indices'] as $idx) { $lines[] = '  ' . $idx['name'] . ': ' . $idx['level'] . ' - ' . $idx['description']; } } } return implode("\n", $lines); } public function get_weather_text($city_name) { $data = $this->query($city_name); return $this->format_output($data); } } 